const headingTitles = {
  "README.md": {
    "Cases FSI": "Prática de entrevista"
  },
  "technical-knowledge/01-fundamentals/README.md": {
    "Fundamentos para sustentar os cases": "Fundamentos para decisões de arquitetura"
  }
};
export const visibleHeadingTitle = (title, source) => headingTitles[source]?.[title] || title;
export function projectMainMarkdown(markdown, source) {
  if (source.startsWith('cases/')) return markdown;
  const edits = caseReferenceEdits[source] || {};
  const originalLines = new Set(markdown.split('\n'));
  for (const expected of Object.keys(edits)) {
    if (!originalLines.has(expected)) throw new Error(`Revisar projeção de referência: ${source}. Um trecho curado foi alterado; preserve a explicação antes de atualizar a regra.`);
  }
  let text = markdown.split('\n').flatMap(line => edits[line] === '' ? [] : [edits[line] ?? line]).join('\n');
  if (source === 'README.md') {
    text = text.replace('System Design\n          ↓\n          ↓\nLeadership Principles', 'System Design\n          ↓\nLeadership Principles');
    text = text.replace(/(## Cases FSI\n[\s\S]*?)\n\|---\|---\|\n/, '$1\n');
  }
  if (source === 'technical-knowledge/README.md') text = text.replace('System Design\n    ↓\n    ↓\nMock Interviews', 'System Design\n    ↓\nMock Interviews');
  return text;
}
